'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Float32Array = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Float32Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'a typed array instance has a `map` method', function test( t ) {
	var arr = new Float32Array( 2 );
	t.strictEqual( hasProp( arr, 'map' ), true, 'has property' );
	t.strictEqual( isFunction( arr.map ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a typed array instance', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float32Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.map.call( value, scale );
		};
	}

	function scale( v ) {
		return v * 2.0;
	}
});

tape( 'the method throws an error if provided a first argument which is not a function', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float32Array( 10 );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.map( value );
		};
	}
});

tape( 'the method returns an empty array if operating on an empty typed array', function test( t ) {
	var arr;
	var out;

	arr = new Float32Array();
	out = arr.map( scale );

	t.strictEqual( out instanceof Float32Array, true, 'returns expected value' );
	t.strictEqual( out.length, 0, 'returns expected value' );
	t.notEqual( out, arr, 'returns a new instance' );
	t.end();

	function scale( v ) {
		return v * 2.0;
	}
});

tape( 'the method returns a new typed array containing elements which are the result of a callback function', function test( t ) {
	var actual;
	var arr;

	arr = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	actual = arr.map( scale );

	t.strictEqual( actual instanceof Float32Array, true, 'returns expected value' );
	t.strictEqual( actual.length, 3, 'returns expected value' );
	t.notEqual( actual, arr, 'returns a new instance' );
	t.strictEqual( actual[ 0 ], 2.0, 'returns expected value' );
	t.strictEqual( actual[ 1 ], 4.0, 'returns expected value' );
	t.strictEqual( actual[ 2 ], 6.0, 'returns expected value' );
	t.end();

	function scale( v ) {
		return v * 2.0;
	}
});

tape( 'the method supports providing an execution context', function test( t ) {
	var actual;
	var arr;
	var ctx;

	arr = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	ctx = {
		'count': 0
	};
	actual = arr.map( scale, ctx );

	t.strictEqual( actual instanceof Float32Array, true, 'returns expected value' );
	t.strictEqual( actual.length, 3, 'returns expected value' );
	t.strictEqual( actual[ 0 ], 3.0, 'returns expected value' );
	t.strictEqual( actual[ 1 ], 6.0, 'returns expected value' );
	t.strictEqual( actual[ 2 ], 9.0, 'returns expected value' );
	t.strictEqual( ctx.count, 3, 'returns expected value' );
	t.end();

	function scale( v ) {
		this.count += 1; // eslint-disable-line no-invalid-this
		return v * 3.0;
	}
});
